/* ShiftWise Design System */
@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap');

:root {
  --primary: #0F172A;
  --primary-light: #1E293B;
  --accent: #F97316;
  --accent-hover: #EA580C;
  --secondary: #0051C3;
  --secondary-hover: #0041A3;
  --background: #FFFFFF;
  --surface: #F8FAFC;
  --text: #1E293B;
  --text-muted: #64748B;
  --text-light: #94A3B8;
  --border: #E2E8F0;
  --success: #10B981;
  --error: #DE5052;
  --shadow-sm: 0 1px 2px 0 rgba(0,0,0,0.05);
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --font-heading: 'Outfit', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--background);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: all 150ms ease;
}

.btn-primary {
  background: var(--accent);
  color: white;
}

.btn-primary:hover {
  background: var(--accent-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: var(--primary);
  color: white;
}

.btn-secondary:hover {
  background: var(--primary-light);
  transform: translateY(-2px);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary);
  color: white;
}

.btn-lg {
  padding: 1rem 2rem;
  font-size: 1.125rem;
}

/* Header / Navigation */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.logo span {
  color: var(--accent);
}

.nav-links {
  display: none;
  list-style: none;
  gap: 2rem;
}

.nav-links a {
  font-weight: 500;
  color: var(--text-muted);
  transition: color 150ms;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--accent);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 0.5rem;
  background: none;
  border: none;
  cursor: pointer;
}

.mobile-toggle span {
  width: 24px;
  height: 2px;
  background: var(--primary);
  transition: all 200ms;
}

.mobile-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}

.mobile-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Navigation */
.mobile-nav {
  position: fixed;
  top: 73px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--background);
  padding: 2rem;
  transform: translateX(100%);
  transition: transform 300ms ease;
  z-index: 99;
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.mobile-nav-links a {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text);
}

.mobile-nav-cta {
  margin-top: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

@media (min-width: 768px) {
  .nav-links {
    display: flex;
  }

  .mobile-toggle {
    display: none;
  }

  .mobile-nav {
    display: none;
  }
}

/* Hero Section */
.hero {
  padding: 5rem 0;
  text-align: center;
  background: linear-gradient(180deg, var(--surface) 0%, var(--background) 100%);
}

.hero h1 {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  color: var(--primary);
  margin-bottom: 1.5rem;
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-muted);
  max-width: 650px;
  margin: 0 auto 2.5rem;
}

.hero-buttons {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  justify-content: center;
  align-items: center;
}

@media (min-width: 480px) {
  .hero-buttons {
    flex-direction: row;
  }
}

/* Section Styles */
.section {
  padding: 5rem 0;
}

.section-sm {
  padding: 3rem 0;
}

.section-dark {
  background: var(--primary);
  color: white;
}

.section-light {
  background: var(--surface);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 3rem;
}

.section-header h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  color: var(--primary);
  margin-bottom: 1rem;
}

.section-header p {
  color: var(--text-muted);
  font-size: 1.125rem;
}

.section-dark .section-header h2 {
  color: white;
}

.section-dark .section-header p {
  color: var(--text-light);
}

/* Feature Cards */
.features-grid {
  display: grid;
  gap: 2rem;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.feature-card {
  background: var(--background);
  padding: 2rem;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  transition: all 200ms ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.feature-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--accent), #FB923C);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}

.feature-icon svg {
  width: 28px;
  height: 28px;
  color: white;
}

.feature-card h3 {
  font-size: 1.25rem;
  color: var(--primary);
  margin-bottom: 0.75rem;
}

.feature-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* How It Works */
.steps-grid {
  display: grid;
  gap: 2rem;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.step {
  text-align: center;
  padding: 1.5rem;
}

.step-number {
  width: 48px;
  height: 48px;
  background: var(--accent);
  color: white;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
}

.step h3 {
  font-size: 1.125rem;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.step p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Stats Banner */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

@media (min-width: 768px) {
  .stats-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 800;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.section-dark .stat-label {
  color: var(--text-light);
}

/* Testimonials */
.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 400ms ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 2.5rem;
  background: var(--background);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  text-align: center;
}

.testimonial-card p {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text);
  margin-bottom: 1.5rem;
  line-height: 1.7;
}

.testimonial-author {
  font-weight: 600;
  color: var(--primary);
}

.testimonial-role {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--border);
  background: var(--background);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 150ms;
}

.carousel-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all 150ms;
}

.carousel-dot.active {
  background: var(--accent);
  width: 24px;
  border-radius: 5px;
}

/* Pricing */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.toggle-label {
  font-weight: 500;
  color: var(--text-muted);
}

.toggle-label.active {
  color: var(--primary);
}

.toggle-switch {
  position: relative;
  width: 56px;
  height: 28px;
  background: var(--border);
  border-radius: 14px;
  cursor: pointer;
  transition: background 200ms;
}

.toggle-switch.active {
  background: var(--accent);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 24px;
  height: 24px;
  background: white;
  border-radius: 50%;
  transition: transform 200ms;
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(28px);
}

.save-badge {
  background: var(--success);
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.5rem;
  border-radius: 9999px;
}

.pricing-grid {
  display: grid;
  gap: 2rem;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  max-width: 1000px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--background);
  border: 2px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  position: relative;
  transition: all 200ms;
}

.pricing-card.featured {
  border-color: var(--accent);
  box-shadow: var(--shadow-lg);
}

.pricing-card:hover {
  transform: translateY(-4px);
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 9999px;
}

.pricing-card h3 {
  font-size: 1.25rem;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.pricing-card .price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.pricing-card .price span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--text-muted);
}

.pricing-card .price-desc {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-bottom: 1.5rem;
}

.pricing-features {
  list-style: none;
  margin-bottom: 2rem;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--text);
}

.pricing-features li svg {
  width: 20px;
  height: 20px;
  color: var(--success);
  flex-shrink: 0;
}

.pricing-features li.disabled {
  color: var(--text-light);
}

.pricing-features li.disabled svg {
  color: var(--text-light);
}

.pricing-card .btn {
  width: 100%;
}

/* FAQ */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5rem 0;
  background: none;
  border: none;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--primary);
  text-align: left;
  cursor: pointer;
}

.faq-question svg {
  width: 24px;
  height: 24px;
  color: var(--text-muted);
  transition: transform 200ms;
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer p {
  padding-bottom: 1.5rem;
  color: var(--text-muted);
}

/* CTA Section */
.cta-section {
  text-align: center;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  color: white;
}

.cta-section h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  margin-bottom: 1rem;
}

.cta-section p {
  color: var(--text-light);
  font-size: 1.125rem;
  margin-bottom: 2rem;
}

/* Team Grid */
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  max-width: 900px;
  margin: 0 auto;
}

.team-member {
  text-align: center;
}

.team-avatar {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #FB923C);
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 700;
  color: white;
}

.team-member h4 {
  font-size: 1rem;
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.team-member p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* Contact Form */
.contact-grid {
  display: grid;
  gap: 3rem;
  grid-template-columns: 1fr;
}

@media (min-width: 768px) {
  .contact-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-weight: 500;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.875rem 1rem;
  font-family: var(--font-body);
  font-size: 1rem;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background: var(--background);
  transition: border-color 150ms;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--accent);
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: var(--error);
}

.form-group .error-message {
  color: var(--error);
  font-size: 0.875rem;
  margin-top: 0.5rem;
  display: none;
}

.form-group.has-error .error-message {
  display: block;
}

.form-group textarea {
  min-height: 150px;
  resize: vertical;
}

.form-success {
  display: none;
  padding: 2rem;
  background: var(--surface);
  border-radius: var(--radius-lg);
  text-align: center;
}

.form-success.show {
  display: block;
}

.form-success svg {
  width: 64px;
  height: 64px;
  color: var(--success);
  margin-bottom: 1rem;
}

.form-success h3 {
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.form-success p {
  color: var(--text-muted);
}

/* Office Locations */
.office-list {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.office-item h4 {
  font-size: 1rem;
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.office-item p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Footer */
.footer {
  background: var(--primary);
  color: white;
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  gap: 2.5rem;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  margin-bottom: 3rem;
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .logo {
  color: white;
  margin-bottom: 1rem;
}

.footer-brand p {
  color: var(--text-light);
  font-size: 0.9375rem;
}

.footer-col h5 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-light);
  margin-bottom: 1rem;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: 0.75rem;
}

.footer-col ul a {
  color: white;
  font-size: 0.9375rem;
  transition: color 150ms;
}

.footer-col ul a:hover {
  color: var(--accent);
}

.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  text-align: center;
  color: var(--text-light);
  font-size: 0.875rem;
}

/* Feature Sections (for features page) */
.feature-section {
  display: grid;
  gap: 3rem;
  align-items: center;
  grid-template-columns: 1fr;
}

@media (min-width: 768px) {
  .feature-section {
    grid-template-columns: 1fr 1fr;
  }

  .feature-section.reverse {
    direction: rtl;
  }

  .feature-section.reverse > * {
    direction: ltr;
  }
}

.feature-content h2 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  color: var(--primary);
  margin-bottom: 1rem;
}

.feature-content p {
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.feature-list {
  list-style: none;
}

.feature-list li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.feature-list li svg {
  width: 20px;
  height: 20px;
  color: var(--accent);
  flex-shrink: 0;
  margin-top: 0.25rem;
}

.feature-visual {
  background: linear-gradient(135deg, var(--surface), #E2E8F0);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
}

.feature-visual svg {
  width: 40%;
  height: 40%;
  color: var(--text-light);
}

/* Integrations Grid */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}

.integration-category h4 {
  font-size: 1rem;
  color: var(--primary);
  margin-bottom: 0.75rem;
}

.integration-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.integration-list li {
  background: var(--surface);
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* Utilities */
.text-center { text-align: center; }
.text-muted { color: var(--text-muted); }
.mt-2 { margin-top: 2rem; }
.mb-2 { margin-bottom: 2rem; }

/* ShiftWise Design System */
@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap');

:root {
  --primary: #0F172A;
  --primary-light: #1E293B;
  --accent: #F97316;
  --accent-hover: #EA580C;
  --secondary: #0051C3;
  --secondary-hover: #0041A3;
  --background: #FFFFFF;
  --surface: #F8FAFC;
  --text: #1E293B;
  --text-muted: #64748B;
  --text-light: #94A3B8;
  --border: #E2E8F0;
  --success: #10B981;
  --error: #DE5052;
  --shadow-sm: 0 1px 2px 0 rgba(0,0,0,0.05);
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --font-heading: 'Outfit', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--background);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: all 150ms ease;
}

.btn-primary {
  background: var(--accent);
  color: white;
}

.btn-primary:hover {
  background: var(--accent-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: var(--primary);
  color: white;
}

.btn-secondary:hover {
  background: var(--primary-light);
  transform: translateY(-2px);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary);
  color: white;
}

.btn-lg {
  padding: 1rem 2rem;
  font-size: 1.125rem;
}

/* Header / Navigation */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.logo span {
  color: var(--accent);
}

.nav-links {
  display: none;
  list-style: none;
  gap: 2rem;
}

.nav-links a {
  font-weight: 500;
  color: var(--text-muted);
  transition: color 150ms;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--accent);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 0.5rem;
  background: none;
  border: none;
  cursor: pointer;
}

.mobile-toggle span {
  width: 24px;
  height: 2px;
  background: var(--primary);
  transition: all 200ms;
}

.mobile-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}

.mobile-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Navigation */
.mobile-nav {
  position: fixed;
  top: 73px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--background);
  padding: 2rem;
  transform: translateX(100%);
  transition: transform 300ms ease;
  z-index: 99;
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.mobile-nav-links a {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text);
}

.mobile-nav-cta {
  margin-top: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

@media (min-width: 768px) {
  .nav-links {
    display: flex;
  }

  .mobile-toggle {
    display: none;
  }

  .mobile-nav {
    display: none;
  }
}

/* Hero Section */
.hero {
  padding: 5rem 0;
  text-align: center;
  background: linear-gradient(180deg, var(--surface) 0%, var(--background) 100%);
}

.hero h1 {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  color: var(--primary);
  margin-bottom: 1.5rem;
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-muted);
  max-width: 650px;
  margin: 0 auto 2.5rem;
}

.hero-buttons {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  justify-content: center;
  align-items: center;
}

@media (min-width: 480px) {
  .hero-buttons {
    flex-direction: row;
  }
}

/* Section Styles */
.section {
  padding: 5rem 0;
}

.section-sm {
  padding: 3rem 0;
}

.section-dark {
  background: var(--primary);
  color: white;
}

.section-light {
  background: var(--surface);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 3rem;
}

.section-header h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  color: var(--primary);
  margin-bottom: 1rem;
}

.section-header p {
  color: var(--text-muted);
  font-size: 1.125rem;
}

.section-dark .section-header h2 {
  color: white;
}

.section-dark .section-header p {
  color: var(--text-light);
}

/* Feature Cards */
.features-grid {
  display: grid;
  gap: 2rem;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.feature-card {
  background: var(--background);
  padding: 2rem;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  transition: all 200ms ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.feature-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--accent), #FB923C);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}

.feature-icon svg {
  width: 28px;
  height: 28px;
  color: white;
}

.feature-card h3 {
  font-size: 1.25rem;
  color: var(--primary);
  margin-bottom: 0.75rem;
}

.feature-card p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* How It Works */
.steps-grid {
  display: grid;
  gap: 2rem;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.step {
  text-align: center;
  padding: 1.5rem;
}

.step-number {
  width: 48px;
  height: 48px;
  background: var(--accent);
  color: white;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
}

.step h3 {
  font-size: 1.125rem;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.step p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Stats Banner */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

@media (min-width: 768px) {
  .stats-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 800;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.section-dark .stat-label {
  color: var(--text-light);
}

/* Testimonials */
.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 400ms ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 2.5rem;
  background: var(--background);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  text-align: center;
}

.testimonial-card p {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text);
  margin-bottom: 1.5rem;
  line-height: 1.7;
}

.testimonial-author {
  font-weight: 600;
  color: var(--primary);
}

.testimonial-role {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--border);
  background: var(--background);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 150ms;
}

.carousel-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all 150ms;
}

.carousel-dot.active {
  background: var(--accent);
  width: 24px;
  border-radius: 5px;
}

/* Pricing */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.toggle-label {
  font-weight: 500;
  color: var(--text-muted);
}

.toggle-label.active {
  color: var(--primary);
}

.toggle-switch {
  position: relative;
  width: 56px;
  height: 28px;
  background: var(--border);
  border-radius: 14px;
  cursor: pointer;
  transition: background 200ms;
}

.toggle-switch.active {
  background: var(--accent);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 24px;
  height: 24px;
  background: white;
  border-radius: 50%;
  transition: transform 200ms;
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(28px);
}

.save-badge {
  background: var(--success);
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.5rem;
  border-radius: 9999px;
}

.pricing-grid {
  display: grid;
  gap: 2rem;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  max-width: 1000px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--background);
  border: 2px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  position: relative;
  transition: all 200ms;
}

.pricing-card.featured {
  border-color: var(--accent);
  box-shadow: var(--shadow-lg);
}

.pricing-card:hover {
  transform: translateY(-4px);
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 9999px;
}

.pricing-card h3 {
  font-size: 1.25rem;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.pricing-card .price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.pricing-card .price span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--text-muted);
}

.pricing-card .price-desc {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-bottom: 1.5rem;
}

.pricing-features {
  list-style: none;
  margin-bottom: 2rem;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--text);
}

.pricing-features li svg {
  width: 20px;
  height: 20px;
  color: var(--success);
  flex-shrink: 0;
}

.pricing-features li.disabled {
  color: var(--text-light);
}

.pricing-features li.disabled svg {
  color: var(--text-light);
}

.pricing-card .btn {
  width: 100%;
}

/* FAQ */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5rem 0;
  background: none;
  border: none;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--primary);
  text-align: left;
  cursor: pointer;
}

.faq-question svg {
  width: 24px;
  height: 24px;
  color: var(--text-muted);
  transition: transform 200ms;
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer p {
  padding-bottom: 1.5rem;
  color: var(--text-muted);
}

/* CTA Section */
.cta-section {
  text-align: center;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  color: white;
}

.cta-section h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  margin-bottom: 1rem;
}

.cta-section p {
  color: var(--text-light);
  font-size: 1.125rem;
  margin-bottom: 2rem;
}

/* Team Grid */
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  max-width: 900px;
  margin: 0 auto;
}

.team-member {
  text-align: center;
}

.team-avatar {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #FB923C);
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 700;
  color: white;
}

.team-member h4 {
  font-size: 1rem;
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.team-member p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* Contact Form */
.contact-grid {
  display: grid;
  gap: 3rem;
  grid-template-columns: 1fr;
}

@media (min-width: 768px) {
  .contact-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-weight: 500;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.875rem 1rem;
  font-family: var(--font-body);
  font-size: 1rem;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background: var(--background);
  transition: border-color 150ms;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--accent);
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: var(--error);
}

.form-group .error-message {
  color: var(--error);
  font-size: 0.875rem;
  margin-top: 0.5rem;
  display: none;
}

.form-group.has-error .error-message {
  display: block;
}

.form-group textarea {
  min-height: 150px;
  resize: vertical;
}

.form-success {
  display: none;
  padding: 2rem;
  background: var(--surface);
  border-radius: var(--radius-lg);
  text-align: center;
}

.form-success.show {
  display: block;
}

.form-success svg {
  width: 64px;
  height: 64px;
  color: var(--success);
  margin-bottom: 1rem;
}

.form-success h3 {
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.form-success p {
  color: var(--text-muted);
}

/* Office Locations */
.office-list {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.office-item h4 {
  font-size: 1rem;
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.office-item p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Footer */
.footer {
  background: var(--primary);
  color: white;
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  gap: 2.5rem;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  margin-bottom: 3rem;
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .logo {
  color: white;
  margin-bottom: 1rem;
}

.footer-brand p {
  color: var(--text-light);
  font-size: 0.9375rem;
}

.footer-col h5 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-light);
  margin-bottom: 1rem;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: 0.75rem;
}

.footer-col ul a {
  color: white;
  font-size: 0.9375rem;
  transition: color 150ms;
}

.footer-col ul a:hover {
  color: var(--accent);
}

.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  text-align: center;
  color: var(--text-light);
  font-size: 0.875rem;
}

/* Feature Sections (for features page) */
.feature-section {
  display: grid;
  gap: 3rem;
  align-items: center;
  grid-template-columns: 1fr;
}

@media (min-width: 768px) {
  .feature-section {
    grid-template-columns: 1fr 1fr;
  }

  .feature-section.reverse {
    direction: rtl;
  }

  .feature-section.reverse > * {
    direction: ltr;
  }
}

.feature-content h2 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  color: var(--primary);
  margin-bottom: 1rem;
}

.feature-content p {
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.feature-list {
  list-style: none;
}

.feature-list li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.feature-list li svg {
  width: 20px;
  height: 20px;
  color: var(--accent);
  flex-shrink: 0;
  margin-top: 0.25rem;
}

.feature-visual {
  background: linear-gradient(135deg, var(--surface), #E2E8F0);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
}

.feature-visual svg {
  width: 40%;
  height: 40%;
  color: var(--text-light);
}

/* Integrations Grid */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}

.integration-category h4 {
  font-size: 1rem;
  color: var(--primary);
  margin-bottom: 0.75rem;
}

.integration-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.integration-list li {
  background: var(--surface);
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* Utilities */
.text-center { text-align: center; }
.text-muted { color: var(--text-muted); }
.mt-2 { margin-top: 2rem; }
.mb-2 { margin-bottom: 2rem; }

